-- Initial PostgreSQL schema. Application identifiers are generated by Prisma.

CREATE TABLE "Organization" (
    "id" TEXT NOT NULL,
    CONSTRAINT "Organization_pkey" PRIMARY KEY ("id"),
    "name" TEXT NOT NULL,
    "demo" BOOLEAN NOT NULL DEFAULT false
);

CREATE TABLE "User" (
    "id" TEXT NOT NULL,
    CONSTRAINT "User_pkey" PRIMARY KEY ("id"),
    "email" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "passwordHash" TEXT NOT NULL,
    "role" TEXT NOT NULL DEFAULT 'VIEWER',
    "organizationId" TEXT NOT NULL
);

CREATE TABLE "Gallery" (
    "id" TEXT NOT NULL,
    CONSTRAINT "Gallery_pkey" PRIMARY KEY ("id"),
    "name" TEXT NOT NULL,
    "timezone" TEXT NOT NULL DEFAULT 'America/Denver',
    "organizationId" TEXT NOT NULL
);

CREATE TABLE "Station" (
    "id" TEXT NOT NULL,
    CONSTRAINT "Station_pkey" PRIMARY KEY ("id"),
    "name" TEXT NOT NULL,
    "location" TEXT NOT NULL,
    "hardware" TEXT NOT NULL DEFAULT 'Audio player gateway',
    "enabled" BOOLEAN NOT NULL DEFAULT true,
    "maintenance" BOOLEAN NOT NULL DEFAULT false,
    "galleryId" TEXT NOT NULL
);

CREATE TABLE "Device" (
    "id" TEXT NOT NULL,
    CONSTRAINT "Device_pkey" PRIMARY KEY ("id"),
    "name" TEXT NOT NULL,
    "stationId" TEXT NOT NULL,
    "simulated" BOOLEAN NOT NULL DEFAULT false,
    "lastHeartbeat" TIMESTAMP(3)
);

CREATE TABLE "DeviceCredential" (
    "id" TEXT NOT NULL,
    CONSTRAINT "DeviceCredential_pkey" PRIMARY KEY ("id"),
    "tokenHash" TEXT NOT NULL,
    "deviceId" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "revokedAt" TIMESTAMP(3)
);

CREATE TABLE "RawEvent" (
    "id" TEXT NOT NULL,
    CONSTRAINT "RawEvent_pkey" PRIMARY KEY ("id"),
    "eventId" TEXT NOT NULL,
    "stationId" TEXT NOT NULL,
    "deviceId" TEXT NOT NULL,
    "type" TEXT NOT NULL,
    "timestamp" TIMESTAMP(3) NOT NULL,
    "ingestedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "sourceType" TEXT NOT NULL,
    "sourceId" TEXT NOT NULL,
    "schemaVersion" INTEGER NOT NULL DEFAULT 1,
    "sessionKey" TEXT,
    "metadata" JSONB NOT NULL DEFAULT '{}',
    "duplicateCount" INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE "ListeningSession" (
    "id" TEXT NOT NULL,
    CONSTRAINT "ListeningSession_pkey" PRIMARY KEY ("id"),
    "stationId" TEXT NOT NULL,
    "sessionKey" TEXT NOT NULL,
    "deviceId" TEXT NOT NULL,
    "startedAt" TIMESTAMP(3),
    "endedAt" TIMESTAMP(3),
    "durationSeconds" DOUBLE PRECISION,
    "sourceType" TEXT NOT NULL,
    "confidence" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "trackId" TEXT,
    "flags" JSONB NOT NULL,
    "eventIds" JSONB NOT NULL
);

CREATE TABLE "AudioContent" (
    "id" TEXT NOT NULL,
    CONSTRAINT "AudioContent_pkey" PRIMARY KEY ("id"),
    "title" TEXT NOT NULL,
    "organizationId" TEXT NOT NULL,
    "durationSeconds" INTEGER
);

CREATE TABLE "DataQualityFlag" (
    "id" TEXT NOT NULL,
    CONSTRAINT "DataQualityFlag_pkey" PRIMARY KEY ("id"),
    "eventId" TEXT NOT NULL,
    "code" TEXT NOT NULL,
    "detail" TEXT NOT NULL
);

CREATE TABLE "MeasurementConfiguration" (
    "id" TEXT NOT NULL,
    CONSTRAINT "MeasurementConfiguration_pkey" PRIMARY KEY ("id"),
    "organizationId" TEXT NOT NULL,
    "engagedSeconds" INTEGER NOT NULL DEFAULT 60,
    "maxSessionSeconds" INTEGER NOT NULL DEFAULT 14400,
    "heartbeatTimeoutSeconds" INTEGER NOT NULL DEFAULT 180,
    "reportTimezone" TEXT NOT NULL DEFAULT 'America/Denver'
);

CREATE TABLE "Report" (
    "id" TEXT NOT NULL,
    CONSTRAINT "Report_pkey" PRIMARY KEY ("id"),
    "organizationId" TEXT NOT NULL,
    "periodStart" TIMESTAMP(3) NOT NULL,
    "periodEnd" TIMESTAMP(3) NOT NULL,
    "sourceType" TEXT NOT NULL,
    "timezone" TEXT NOT NULL,
    "snapshot" JSONB NOT NULL,
    "generatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "AuditLog" (
    "id" TEXT NOT NULL,
    CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"),
    "organizationId" TEXT NOT NULL,
    "actor" TEXT NOT NULL,
    "action" TEXT NOT NULL,
    "detail" JSONB NOT NULL DEFAULT '{}',
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "RateBucket" (
    "key" TEXT NOT NULL,
    CONSTRAINT "RateBucket_pkey" PRIMARY KEY ("key"),
    "count" INTEGER NOT NULL DEFAULT 1,
    "expiresAt" TIMESTAMP(3) NOT NULL
);

CREATE UNIQUE INDEX "User_email_key" ON "User"("email");

CREATE INDEX "Station_galleryId_idx" ON "Station"("galleryId");

CREATE UNIQUE INDEX "DeviceCredential_tokenHash_key" ON "DeviceCredential"("tokenHash");

CREATE UNIQUE INDEX "RawEvent_deviceId_eventId_key" ON "RawEvent"("deviceId", "eventId");

CREATE INDEX "RawEvent_stationId_timestamp_idx" ON "RawEvent"("stationId", "timestamp");

CREATE INDEX "RawEvent_stationId_sourceType_sessionKey_idx" ON "RawEvent"("stationId", "sourceType", "sessionKey");

CREATE INDEX "ListeningSession_stationId_startedAt_idx" ON "ListeningSession"("stationId", "startedAt");

CREATE UNIQUE INDEX "ListeningSession_stationId_deviceId_sourceType_sessionKey_key" ON "ListeningSession"("stationId", "deviceId", "sourceType", "sessionKey");

CREATE UNIQUE INDEX "DataQualityFlag_eventId_code_key" ON "DataQualityFlag"("eventId", "code");

CREATE UNIQUE INDEX "MeasurementConfiguration_organizationId_key" ON "MeasurementConfiguration"("organizationId");

CREATE UNIQUE INDEX "Report_organizationId_periodStart_periodEnd_sourceType_key" ON "Report"("organizationId", "periodStart", "periodEnd", "sourceType");

CREATE INDEX "AuditLog_organizationId_createdAt_idx" ON "AuditLog"("organizationId", "createdAt");

CREATE INDEX "RateBucket_expiresAt_idx" ON "RateBucket"("expiresAt");

ALTER TABLE "User" ADD CONSTRAINT "User_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "Gallery" ADD CONSTRAINT "Gallery_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "Station" ADD CONSTRAINT "Station_galleryId_fkey" FOREIGN KEY ("galleryId") REFERENCES "Gallery"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "Device" ADD CONSTRAINT "Device_stationId_fkey" FOREIGN KEY ("stationId") REFERENCES "Station"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "DeviceCredential" ADD CONSTRAINT "DeviceCredential_deviceId_fkey" FOREIGN KEY ("deviceId") REFERENCES "Device"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "RawEvent" ADD CONSTRAINT "RawEvent_stationId_fkey" FOREIGN KEY ("stationId") REFERENCES "Station"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "RawEvent" ADD CONSTRAINT "RawEvent_deviceId_fkey" FOREIGN KEY ("deviceId") REFERENCES "Device"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "ListeningSession" ADD CONSTRAINT "ListeningSession_stationId_fkey" FOREIGN KEY ("stationId") REFERENCES "Station"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "ListeningSession" ADD CONSTRAINT "ListeningSession_deviceId_fkey" FOREIGN KEY ("deviceId") REFERENCES "Device"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "AudioContent" ADD CONSTRAINT "AudioContent_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "DataQualityFlag" ADD CONSTRAINT "DataQualityFlag_eventId_fkey" FOREIGN KEY ("eventId") REFERENCES "RawEvent"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "MeasurementConfiguration" ADD CONSTRAINT "MeasurementConfiguration_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "Report" ADD CONSTRAINT "Report_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

CREATE INDEX "User_organizationId_idx" ON "User"("organizationId");

CREATE INDEX "Gallery_organizationId_idx" ON "Gallery"("organizationId");

CREATE INDEX "Device_stationId_idx" ON "Device"("stationId");

CREATE INDEX "DeviceCredential_deviceId_idx" ON "DeviceCredential"("deviceId");

CREATE INDEX "RawEvent_deviceId_timestamp_idx" ON "RawEvent"("deviceId", "timestamp");

CREATE INDEX "Report_organizationId_generatedAt_idx" ON "Report"("organizationId", "generatedAt");
